+/**
+ * Variance per item between two days (inclusive): `theoretical` use from the
+ * sales sold in those days, `actual` use from every consume movement in those
+ * days, and `difference` (actual minus theoretical). Items with neither are left out.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => {
+    const day = dayOf(instant);
+    return day >= from && day <= to;
+  };
+  const round = (n) => Math.round(n * 1000) / 1000;
+  const byItem = new Map();
+  const add = (itemId, key, qty) => {
+    const line = byItem.get(itemId) ?? { itemId, theoretical: 0, actual: 0 };
+    line[key] = round(line[key] + qty);
+    byItem.set(itemId, line);
+  };
+  for (const sale of listSales(store)) {
+    if (!inRange(sale.soldAt)) continue;
+    for (const n of saleNeeds(store, sale)) add(n.itemId, "theoretical", n.qty);
+  }
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0 || !batchItem.has(m.batchId) || !inRange(m.at)) continue;
+    add(batchItem.get(m.batchId), "actual", m.qty);
+  }
+  return [...byItem.values()]
+    .filter((l) => l.theoretical > 0 || l.actual > 0)
+    .map((l) => ({ ...l, difference: round(l.actual - l.theoretical) }))
+    .sort((a, b) => a.itemId - b.itemId);
+}
