+// Sales from the till. Each sale line is `qty` of a dish and uses one portion
+// of the dish's recipe per `qty`. A ticket is imported once; a batch of lines
+// is recorded all or nothing (docs/DATA.md).
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { scaled } from "./recipes.js";
+
+/** Every recorded sale line, in id order. */
+export function listSales(store) {
+  return [...(store.data.sales ?? [])].sort((a, b) => a.id - b.id);
+}
+
+/** Ingredient quantities one sale line uses in theory (empty when its dish or recipe is gone). */
+export function saleNeeds(store, sale) {
+  const dish = (store.data.dishes ?? []).find((d) => d.id === sale.dishId);
+  const recipe = dish && store.data.recipes.find((r) => r.id === dish.recipeId);
+  return recipe ? scaled(recipe, sale.qty).filter((n) => n.qty > 0) : [];
+}
+
+/**
+ * Records sale lines `{ row, ticket, soldAt, dishId, qty }` and consumes their
+ * ingredients (ref `sale:<ticket>`, at `soldAt`). Lines of tickets recorded
+ * before are skipped. One bad line and nothing is recorded; the error names
+ * its `row`. Returns the `{ tickets, dishes }` counts recorded.
+ */
+export function recordSales(store, lines) {
+  for (const l of lines) {
+    const dish = (store.data.dishes ?? []).find((d) => d.id === l.dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `row ${l.row}: unknown dish ${l.dishId}` });
+    if (!store.data.recipes.some((r) => r.id === dish.recipeId))
+      throw new AppError("bad_request", { reason: `row ${l.row}: dish ${l.dishId} has no recipe` });
+  }
+  const known = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const fresh = lines.filter((l) => !known.has(l.ticket));
+  const before = structuredClone(store.data);
+  try {
+    store.data.sales ??= [];
+    for (const l of fresh) {
+      for (const n of saleNeeds(store, l)) {
+        try {
+          consume(store, n.itemId, n.qty, { at: l.soldAt, ref: `sale:${l.ticket}` });
+        } catch (e) {
+          if (e instanceof AppError && e.code === "not_enough_stock")
+            throw new AppError("sale_not_enough_stock", { ...e.params, row: l.row });
+          throw e;
+        }
+      }
+      store.data.sales.push({ id: store.nextId("sale"), ticket: l.ticket, soldAt: l.soldAt, dishId: l.dishId, qty: l.qty });
+    }
+  } catch (e) {
+    store.data = before;
+    throw e;
+  }
+  return { tickets: new Set(fresh.map((l) => l.ticket)).size, dishes: fresh.length };
+}
